    "Script": "MailManagement = {
 init: async function(app, container) {
  app = app || session.app; container = container || $(".component[name=MailManagement]");
  api.addToMetaCache([{Name:"Mail",Types:[[meta[Mail/QueuedEmail]],[meta[Mail/SentEmail]]]}]);
  api.cache.meta.filter(function(x){return x.Name==="Mail";})[0].Types.push(
   JSON.parse('{"ServerTypeName":"MailSender","Category":"Mail","Properties":[{"Name":"Id","Type":"guid","Template":"key","IsValueType":true,"ShortDisplayName":"Id"},{"Name":"AppId","Type":"number","IsValueType":true,"ShortDisplayName":"AppId"},{"Name":"Name","Type":"string","IsValueType":true,"ShortDisplayName":"Name"},{"Name":"ProviderName","Type":"string","IsValueType":true,"ShortDisplayName":"ProviderName"},{"Name":"User","Type":"string","IsValueType":true,"ShortDisplayName":"User"},{"Name":"Password","Type":"string","IsValueType":true,"ShortDisplayName":"Password"},{"Name":"Host","Type":"string","IsValueType":true,"ShortDisplayName":"Host"},{"Name":"FromEmail","Type":"string","IsValueType":true,"ShortDisplayName":"FromEmail"},{"Name":"Port","Type":"number","IsValueType":true,"ShortDisplayName":"Port"},{"Name":"EnableSSL","Type":"bool","IsValueType":true,"ShortDisplayName":"EnableSSL"}]}'),
   JSON.parse('{"ServerTypeName":"MailReceiver","Category":"Mail","Properties":[{"Name":"Id","Type":"guid","Template":"key","IsValueType":true,"ShortDisplayName":"Id"},{"Name":"AppId","Type":"number","IsValueType":true,"ShortDisplayName":"AppId"},{"Name":"Name","Type":"string","IsValueType":true,"ShortDisplayName":"Name"},{"Name":"ProviderName","Type":"string","IsValueType":true,"ShortDisplayName":"ProviderName"},{"Name":"User","Type":"string","IsValueType":true,"ShortDisplayName":"User"},{"Name":"Password","Type":"string","IsValueType":true,"ShortDisplayName":"Password"},{"Name":"Host","Type":"string","IsValueType":true,"ShortDisplayName":"Host"},{"Name":"Port","Type":"number","IsValueType":true,"ShortDisplayName":"Port"},{"Name":"EnableSSL","Type":"bool","IsValueType":true,"ShortDisplayName":"EnableSSL"},{"Name":"LastReceivedOn","Type":"date","IsValueType":true,"ShortDisplayName":"LastReceivedOn"},{"Name":"IsEnabled","Type":"bool","IsValueType":true,"ShortDisplayName":"IsEnabled"}]}')
  );

  MailManagement.summaryGrid(app,container,"QueuedEmail","queue",[
   {field:"Subject",title:"Title"},
   {field:"SentByUserId",title:"Sent by user"},
   {field:"To",title:"To"}
  ],["Subject","SentByUserId","To"]);
  MailManagement.summaryGrid(app,container,"SentEmail","history",[
   {field:"Subject",title:"Subject"},
   {field:"SentOn",title:"Sent on",type:"date",format:"{0: "+type.dateAndTimeFormat + "}"}
  ],["Subject","SentOn"]);
  MailManagement.endpointGrid(app,container,"MailSender","senders",[
   {field:"Name",title:"Name"},{field:"ProviderName",title:"Provider"},{field:"Host",title:"Host"}
  ],["Id","AppId","Name","ProviderName","User","Password","Host","FromEmail","Port","EnableSSL"],
  {ProviderName:"",FromEmail:"",EnableSSL:true});
  MailManagement.endpointGrid(app,container,"MailReceiver","receivers",[
   {field:"Name",title:"Name"},{field:"ProviderName",title:"Provider"},{field:"Host",title:"Host"}
  ],["Id","AppId","Name","ProviderName","User","Password","Host","Port","EnableSSL","LastReceivedOn","IsEnabled"],
  {ProviderName:"",EnableSSL:true,IsEnabled:true});
 },
 summaryGrid: async function(app,container,setName,target,columns,summaryFields) {
  var endpoint="Mail/"+setName;
  var append="?$filter=AppId eq "+app.Id+(setName==="QueuedEmail"?"&$expand=FailedSends":"");
  var source=await model.getDatasource({endpoint:endpoint,odataAppend:append});
  var grid=new GridWidget($("[name="+target+"]",container),source);
  grid.filterable=true; grid.groupable=false; grid.columns=columns;
  grid.detailTemplate="<div name='mailRecordDetails'></div>";
  grid.detailExpand=function(e){
   var item=grid.dataItem(e.masterRow);
   MailManagement.renderMessageDetails($("[name=mailRecordDetails]",e.detailRow),item,summaryFields,setName);
  };
  if(setName==="QueuedEmail"){
   grid.commands.push({name:"destroy",icon:"k-i-trash",text:"delete"});
   grid.dataBound=function(){
    $("[name=destroy]",grid.gridElement).off("click").on("click",async function(e){
     e.preventDefault(); var item=grid.dataItem($(e.currentTarget).closest("tr"));
     await api.destroy(endpoint+"("+item.Id+")"); notification.success("deleted"); grid.refresh();
    });
   };
  }
  await grid.init();
 },
 endpointGrid: async function(app,container,setName,target,columns,detailFields,defaults) {
  var endpoint="Mail/"+setName;
  var source=await model.getDatasource({endpoint:endpoint,odataAppend:"?$filter=AppId eq "+app.Id});
  var grid=new GridWidget($("[name="+target+"]",container),source);
  grid.filterable=true; grid.groupable=false; grid.editable=false; grid.columns=columns;
  grid.toolbar="<button name='create'><span class='k-icon k-i-plus'></span>new</button>";
  grid.detailTemplate="<div name='mailRecordEditor'></div>";
  grid.detailExpand=function(e){
   MailManagement.renderEditor($("[name=mailRecordEditor]",e.detailRow),grid.dataItem(e.masterRow),endpoint,detailFields,grid);
  };
  grid.commands.push({name:"remove",icon:"k-i-trash",text:"remove"});
  grid.dataBound=function(){
   $("[name=remove]",grid.gridElement).off("click").on("click",async function(e){
    e.preventDefault(); var item=grid.dataItem($(e.currentTarget).closest("tr"));
    await api.destroy(endpoint+"("+item.Id+")"); notification.success("deleted"); grid.refresh();
   });
   $("button[name=create]",grid.gridElement).off("click").on("click",function(e){
    e.preventDefault();
    var data=Object.assign({Id:"00000000-0000-0000-0000-000000000000",AppId:app.Id,Name:"",User:"",Password:"",Host:"",Port:0},defaults);
    var fields=detailFields.filter(function(x){return x!=="Id"&&x!=="AppId"&&x!=="LastReceivedOn";}).map(function(x){return {field:x,title:MailManagement.label(x)};});
    var dialog=new EditorDialog({fields:fields,title:"Create "+setName.replace("Mail","mail ").toLowerCase(),data:data,confirm:"confirm",close:"close"});
    dialog.events.confirm=async function(){await api.add(endpoint,dialog.data.toJSON());dialog.events.close();notification.success("created");grid.refresh();};
    dialog.init();
   });
  };
  await grid.init();
 },
 renderMessageDetails: function(host,item,summaryFields,setName) {
  var id=Guid(),detailsId="mail-details-"+id,previewId="mail-preview-"+id,failuresId="mail-failures-"+id;
  var failuresTab=setName==="QueuedEmail"?"<button class='nav-link' data-bs-toggle='tab' data-bs-target='#"+failuresId+"'>Failed sends</button>":"";
  var failuresPane=setName==="QueuedEmail"?"<div class='tab-pane fade p-3' id='"+failuresId+"'><div name='failures'></div></div>":"";
  host.html("<div class='tab-control'><nav><div class='nav nav-tabs' role='tablist'>"+
   "<button class='nav-link active' data-bs-toggle='tab' data-bs-target='#"+detailsId+"'>Details</button>"+
   "<button class='nav-link' data-bs-toggle='tab' data-bs-target='#"+previewId+"'>Preview</button>"+failuresTab+
   "</div></nav><div class='tab-content'>"+
   "<div class='tab-pane fade show active p-3' id='"+detailsId+"'><dl class='row mb-0' name='fields'></dl></div>"+
   "<div class='tab-pane fade p-3' id='"+previewId+"'><iframe title='Email preview' style='width:100%;min-height:28rem;border:0'></iframe></div>"+failuresPane+
   "</div></div>");
  var fields=api.getType(item.type).Properties.filter(function(x){
   return x.IsValueType&&x.Name!=="Content"&&summaryFields.indexOf(x.Name)<0;
  });
  var list=$("[name=fields]",host);
  fields.forEach(function(field){
   var value=item[field.Name];
   if(value instanceof Date)value=kendo.toString(value,type.dateAndTimeFormat);
   list.append($("<dt class='col-sm-3'></dt>").text(field.ShortDisplayName||MailManagement.label(field.Name)));
   list.append($("<dd class='col-sm-9'></dd>").text(value==null?"":value));
  });
  if(setName==="QueuedEmail"){
   var failures=item.FailedSends||[],table=$("<table class='table table-striped'><thead><tr><th>Attempted on</th><th>Failure reason</th></tr></thead><tbody></tbody></table>");
   failures.forEach(function(failure){
    var attempted=failure.AttemptedOn?kendo.toString(new Date(failure.AttemptedOn),type.dateAndTimeFormat):"";
    var row=$("<tr></tr>"); row.append($("<td></td>").text(attempted)); row.append($("<td></td>").text(failure.FailureReason||"")); $("tbody",table).append(row);
   });
   if(failures.length===0)$("[name=failures]",host).text("No failed sends."); else $("[name=failures]",host).append(table);
  }
  var frame=$("iframe",host)[0],doc=frame.contentDocument||frame.contentWindow.document;
  doc.open(); doc.write(item.Content||""); doc.close();
 },
 renderEditor: function(host,item,endpoint,fields,grid) {
  var form=$("<form class='p-3 mail-record-editor'></form>");
  fields.forEach(function(field){
   var typeInfo=api.getType(item.type).Properties.filter(function(x){return x.Name===field;})[0]||{Type:"string"};
   var readOnly=field==="Id"||field==="AppId"||field==="LastReceivedOn";
   var row=$("<div class='row align-items-center mb-2'></div>");
   row.append($("<label class='col-sm-3 col-form-label'></label>").text(MailManagement.label(field)));
   var value=item[field],input;
   if(typeInfo.Type==="bool"){
    input=$("<input type='checkbox' class='form-check-input' data-field='"+field+"'>").prop("checked",!!value);
   }else{
    input=$("<input class='form-control' data-field='"+field+"'>").val(value==null?"":value);
    if(field==="Password")input.attr("type","password");
    if(typeInfo.Type==="number")input.attr("type","number");
    if(typeInfo.Type==="date")input.attr("type","datetime-local");
   }
   if(readOnly)input.prop("disabled",true);
   row.append($("<div class='col-sm-9'></div>").append(input)); form.append(row);
  });
  form.append("<div class='d-flex justify-content-end pt-2'><button class='btn btn-primary' name='save'><span class='k-icon k-i-save'></span> save</button></div>");
  host.empty().append(form);
  $("button[name=save]",form).on("click",async function(e){
   e.preventDefault();
   $("[data-field]",form).each(function(){
    var input=$(this),field=input.data("field"); if(input.prop("disabled"))return;
    var meta=api.getType(item.type).Properties.filter(function(x){return x.Name===field;})[0]||{Type:"string"};
    var value=meta.Type==="bool"?input.prop("checked"):input.val();
    if(meta.Type==="number")value=parseInt(value)||0;
    item.set(field,value);
   });
   await api.update(endpoint+"("+item.Id+")",item.prepForPush());
   notification.success("saved"); grid.refresh();
  });
 },
 label: function(value) {
  return value.replace(/([a-z0-9])([A-Z])/g,"$1 $2").replace(/^./,function(x){return x.toUpperCase();});
 }
};",
