  {
    "Name": "MailManagement.RetryFailedSends",
    "Key": "Mail",
    "Content": "const renderMailMessageDetails = MailManagement.renderMessageDetails;

MailManagement.renderMessageDetails = function(host, item, summaryFields, setName) {
    renderMailMessageDetails(host, item, summaryFields, setName);
    const failures = item.FailedSends || [];
    const failureHost = $("[name=failures]", host);
    if (setName !== "QueuedEmail" || failures.length === 0) return;
    const retry = $("<button class='btn btn-primary mb-3' name='retryFailedSends'><span class='k-icon k-i-arrow-rotate-cw'></span> [resource_displayname[retrysending]]</button>");
    failureHost.prepend(retry);
    retry.on("click", async function() {
        retry.prop("disabled", true);
        try {
            await api.post("Mail/QueuedEmail(" + item.Id + ")/Retry", {});
            item.FailedSends = [];
            failureHost.text("[resource_displayname[retryqueued]]");
            notification.success("[resource_displayname[retryqueued]]");
        } catch (err) {
            retry.prop("disabled", false);
            error(err);
        }
    });
};",
